Algorithm Intercambio
  Define a As Integer <- 1;
  Define b As Integer <- 2;
  Define auxiliar As Integer;
  auxiliar <- a;
  a <- b;
  b <- auxiliar;
  Write a, " ", b;
EndAlgorithm

Algorithm Tipos
  Define x As Integer <- 1;
  x <- "uno";
  Write x;
EndAlgorithm

Algorithm Fuera
  Dimension notas[3] As Integer;
  notas[3] <- 1;
EndAlgorithm
